create role anon; create role authenticated; create role service_role bypassrls;
create schema auth;
create table auth.users(id uuid primary key,email text);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth to anon,authenticated;
grant execute on function auth.uid() to anon,authenticated;
create table public.logements(id uuid primary key default gen_random_uuid(),created_at timestamptz default now(),nom text not null,type text not null,prix numeric not null,description text,statut text default 'disponible',photos text[] default '{}',surface integer,equipements text[] default '{}');
create table public.reservations(id uuid primary key default gen_random_uuid(),created_at timestamptz default now(),logement_id uuid references public.logements(id) on delete cascade,client_nom text not null,client_email text not null,client_telephone text not null,date_arrivee date not null,date_depart date not null,nombre_nuits integer not null,montant_total numeric not null,montant_paye numeric default 0,methode_paiement text,statut_paiement text default 'non_paye',statut_reservation text default 'demande',notes text);
create table public.contacts(id uuid default gen_random_uuid(),nom text,email text,sujet text,message text,lu boolean default false);
create table public.gallery_images(id uuid,visible boolean);
create schema storage;
create table storage.objects(id uuid,bucket_id text);
alter table storage.objects enable row level security;
grant insert,select,update,delete on storage.objects to authenticated;
create policy "Gallery storage admin insert" on storage.objects for insert to authenticated with check(bucket_id='gallery');
create policy "Gallery storage admin update" on storage.objects for update to authenticated using(bucket_id='gallery');
create policy "Gallery storage admin delete" on storage.objects for delete to authenticated using(bucket_id='gallery');
create policy "Logements storage admin insert" on storage.objects for insert to authenticated with check(bucket_id='logements');
create policy "Logements storage admin update" on storage.objects for update to authenticated using(bucket_id='logements');
create policy "Logements storage admin delete" on storage.objects for delete to authenticated using(bucket_id='logements');
create function public.invoke_send_email(jsonb) returns void language sql as $$select$$;
create function public.trigger_send_email_contact() returns trigger language plpgsql as $$begin return new;end$$;
create function public.trigger_send_email_reservation_insert() returns trigger language plpgsql as $$begin return new;end$$;
create function public.trigger_send_email_reservation_confirmed() returns trigger language plpgsql as $$begin return new;end$$;
